#include "bb_rom.h"
#include <stdio.h>
int main(int argc,char**argv){BBRom r;char e[256],reason[256];int ok;if(argc<2){fprintf(stderr,"Usage: bb-rom-audit <Bubble Bobble ROM> [output.json]\n");return 2;}if(!bb_rom_load(argv[1],&r,e,sizeof(e))){fprintf(stderr,"ROM load failed: %s\n",e);return 3;}ok=bb_rom_is_expected(&r,reason,sizeof(reason));printf("Bubble Bobble ROM audit\nSHA-256: %s\nPayload SHA-256: %s\nPayload CRC32: %08X\nMapper: %d\nPRG: %llu bytes\nCHR: %llu bytes\nVectors: NMI %04X RESET %04X IRQ %04X\nExpected: %s\nReason: %s\n",r.sha256,r.payload_sha256,r.payload_crc32,r.mapper,(unsigned long long)r.prg_size,(unsigned long long)r.chr_size,r.nmi_vector,r.reset_vector,r.irq_vector,ok?"yes":"no",reason);if(argc>=3&&!bb_rom_write_json(&r,argv[2])){fprintf(stderr,"Could not write JSON\n");bb_rom_free(&r);return 4;}bb_rom_free(&r);return ok?0:5;}
